inline bool outbox_wait(int milliseconds) {
	// The collector may run while this thread waits.
	hxn::Blocking zone;
	return hxn_xavi_outbox_wait(milliseconds) != 0;
}

inline int outbox_next() {
	return hxn_xavi_outbox_next();
}

